const num = (n: number) => Math.round(n).toLocaleString('en-MY');
const nav = [{ label: 'Overview', short: 'Overview', icon: LayoutDashboard }, { label: 'Existing Township Analysis', short: 'Existing township', icon: Map }, { label: 'Future Township Planner', short: 'Future township', icon: Building2 }, { label: 'Recommendations & Budget', short: 'Recommendations & budget', icon: Lightbulb }, { label: 'Sustainability Impact & Evidence', short: 'Impact & evidence', icon: ChartNoAxesCombined }];
